                top = max(len(legend) - 1, 0)
                level = legend.get(str(int(round(float(ans["score"])))))
                scale = f" out of {top}" if top else ""
                closest = f' - closest level: "{level}"' if level else ""
                lines.append(f"{qid}: {float(ans['score']):.2f}{scale}{closest}{tail}")
