            elif val is not None:
                out.append(str(val))
        return out

    def _parse_bindings(self) -> dict[str, Any] | None:
        raw = (getattr(self, "bind_parameters_json", "") or "").strip()
        static: dict[str, dict[str, Any]] = {}
        if raw and raw != "{}":
            try:
                parsed = json.loads(raw)
